"use strict";globalThis.onmessage=function(e){const{buf:buf,sampleRate:sampleRate,id:id}=e.data;const samples=new Float32Array(buf);const windowed=applyHannWindow(samples);const result=yinPitchDetect(windowed,sampleRate);let freq=result.freq;let confidence=result.confidence;if(freq>0){const hpsFreq=harmonicProductSpectrum(windowed,sampleRate);if(hpsFreq>0){freq=reconcileDetectors(freq,hpsFreq)}}globalThis.postMessage({freq:freq,confidence:confidence,id:id})};function applyHannWindow(buf){const n=buf.length;const out=new Float32Array(n);for(let i=0;i<n;i++){const w=.5*(1-Math.cos(2*Math.PI*i/(n-1)));out[i]=buf[i]*w}return out}function yinDifferenceFunction(buf,halfLen){const yinBuf=new Float32Array(halfLen);for(let tau=0;tau<halfLen;tau++){let sum=0;for(let j=0;j<halfLen;j++){const d=buf[j]-buf[j+tau];sum+=d*d}yinBuf[tau]=sum}return yinBuf}function yinCumulativeMeanNormalize(yinBuf,halfLen){yinBuf[0]=1;let runningSum=0;for(let tau=1;tau<halfLen;tau++){runningSum+=yinBuf[tau];yinBuf[tau]*=tau/runningSum}}function yinFindTau(yinBuf,minTau,maxTau){const threshold=.15;for(let tau=minTau;tau<maxTau;tau++){if(yinBuf[tau]<threshold){while(tau+1<maxTau&&yinBuf[tau+1]<yinBuf[tau])tau++;return tau}}const fallbackThreshold=.35;let bestVal=Infinity;let bestTau=-1;for(let tau=minTau;tau<maxTau;tau++){if(yinBuf[tau]<bestVal){bestVal=yinBuf[tau];bestTau=tau}}return bestVal<fallbackThreshold?bestTau:-1}function yinParabolicInterpolation(yinBuf,tauEstimate,halfLen){if(tauEstimate>0&&tauEstimate<halfLen-1){const s0=yinBuf[tauEstimate-1];const s1=yinBuf[tauEstimate];const s2=yinBuf[tauEstimate+1];const shift=(s0-s2)/(2*(s0-2*s1+s2));return Number.isFinite(shift)?tauEstimate+shift:tauEstimate}return tauEstimate}function yinPitchDetect(buf,sampleRate){const halfLen=Math.floor(buf.length/2);const yinBuf=yinDifferenceFunction(buf,halfLen);yinCumulativeMeanNormalize(yinBuf,halfLen);const minTau=Math.floor(sampleRate/5e3);const maxTau=Math.min(halfLen-1,Math.floor(sampleRate/20));const tauEstimate=yinFindTau(yinBuf,minTau,maxTau);if(tauEstimate===-1)return{freq:-1,confidence:0};const confidence=1-yinBuf[tauEstimate];const betterTau=yinParabolicInterpolation(yinBuf,tauEstimate,halfLen);const freq=sampleRate/betterTau;if(freq<20||freq>5e3)return{freq:-1,confidence:0};return{freq:freq,confidence:confidence}}function nextPow2(v){let p=1;while(p<v)p<<=1;return p}function fft(re,im,inverse){const n=re.length;const halfN=n>>1;for(let i=1,j=0;i<n;i++){let bit=halfN;while(j&bit){j^=bit;bit>>=1}j^=bit;if(i<j){let tmp=re[i];re[i]=re[j];re[j]=tmp;tmp=im[i];im[i]=im[j];im[j]=tmp}}const angleSign=inverse?1:-1;for(let len=2;len<=n;len<<=1){const halfLen=len>>1;const angle=angleSign*Math.PI/halfLen;const wRe=Math.cos(angle);const wIm=Math.sin(angle);for(let i=0;i<n;i+=len){let curRe=1,curIm=0;for(let j=0;j<halfLen;j++){const a=i+j;const b=a+halfLen;const tRe=curRe*re[b]-curIm*im[b];const tIm=curRe*im[b]+curIm*re[b];re[b]=re[a]-tRe;im[b]=im[a]-tIm;re[a]+=tRe;im[a]+=tIm;const nextRe=curRe*wRe-curIm*wIm;curIm=curRe*wIm+curIm*wRe;curRe=nextRe}}}}function harmonicProductSpectrum(buf,sampleRate){const n=buf.length;const fftSize=nextPow2(n);const re=new Float32Array(fftSize);const im=new Float32Array(fftSize);for(let i=0;i<n;i++)re[i]=buf[i];fft(re,im,false);const mag=new Float32Array(fftSize/2);for(let i=0;i<mag.length;i++){mag[i]=re[i]*re[i]+im[i]*im[i]}const harmonics=4;const minBin=Math.floor(20*fftSize/sampleRate);const maxBin=Math.min(mag.length/harmonics,Math.floor(5e3*fftSize/sampleRate));const hps=new Float32Array(maxBin);for(let i=minBin;i<maxBin;i++){let product=mag[i];for(let h=2;h<=harmonics;h++){product*=mag[i*h]||0}hps[i]=product}let bestBin=minBin;let bestVal=0;for(let i=minBin;i<maxBin;i++){if(hps[i]>bestVal){bestVal=hps[i];bestBin=i}}if(bestVal===0)return-1;if(bestBin>0&&bestBin<maxBin-1){const a=hps[bestBin-1];const b=hps[bestBin];const c=hps[bestBin+1];const shift=(a-c)/(2*(a-2*b+c));if(Number.isFinite(shift)){return(bestBin+shift)*sampleRate/fftSize}}return bestBin*sampleRate/fftSize}function reconcileDetectors(yinFreq,hpsFreq){const ratio=yinFreq/hpsFreq;if(ratio>1.8&&ratio<2.2)return hpsFreq;if(ratio>.45&&ratio<.55)return hpsFreq;if(ratio>2.8&&ratio<3.2)return hpsFreq;return yinFreq}